            ["alignOffsetY"] = 64,
            ["ghost"] = true,
            ["notColliding"] = "local Serial = require \"actions/Serial\"\nlocal Parallel = require \"actions/Parallel\"\nlocal AudioFade = require \"actions/AudioFade\"\nlocal PlayAudio = require \"actions/PlayAudio\"\n\nreturn function(self, player)\n    if not player.walkingThroughHaypatch then\n        return\n    end\n    player.hitHaypatch = false\n    player.walkingThroughHaypatch = false\n\n    player.movespeed = player.origMoveSpeed or player.movespeed\n    self.sprite:setAnimation(\"idle\")\nend",
            ["sprite"] = "../art/sprites/haypatch.png",
            ["whileColliding"] = "local Serial = require \"actions/Serial\"\nlocal Do = require \"actions/Do\"\nlocal Animate = require \"actions/Animate\"\nlocal PlayAudio = require \"actions/PlayAudio\"\n\nreturn function(self, player)\n    if player.hitHaypatch then\n        return\n    end\n    if player.walkingThroughHaypatch then\n        if love.keyboard.isDown(\"up\") or\n           love.keyboard.isDown(\"down\") or\n           love.keyboard.isDown(\"left\") or\n           love.keyboard.isDown(\"right\")\n        then\n            self.sprite:setAnimation(\"waffle\")\n        else\n            self.sprite:setAnimation(\"idle\")\n        end\n        return\n    end\n\n    if not (GameState.leader == \"sonic\" and player.doingSpecialMove) then\n        player.origMoveSpeed = player.movespeed\n        player.movespeed = 1\n        player.walkingThroughHaypatch = true\n        return\n    end\n\n    player.hitHaypatch = true\n    if player:isFacing(\"down\") or player:isFacing(\"up\") then\n        player.specialCollidedY = true\n    else\n        player.specialCollidedX = true\n    end\n\n    self:run {\n        Animate(self.sprite, \"bounce\"),\n        Do(function()\n            self.sprite:setAnimation(\"idle\")\n            player.hitHaypatch = false\n            player.specialCollidedX = false\n            player.specialCollidedY = false\n        end)\n    }\nend"
          }
